VALUES ('clerk_preserve','known',810000.37,89.25,true,'2024-01-02 03:04:05.123456+00','2024-02-03 04:05:06.654321+00');
CREATE SCHEMA deployment_owned;
CREATE TABLE deployment_owned.notes(id text PRIMARY KEY, payload jsonb NOT NULL);
CREATE INDEX notes_payload_idx ON deployment_owned.notes USING gin(payload);
CREATE FUNCTION deployment_owned.keep_note() RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RETURN NEW; END$$;
CREATE TRIGGER keep_note BEFORE UPDATE ON deployment_owned.notes FOR EACH ROW EXECUTE FUNCTION deployment_owned.keep_note();
CREATE POLICY keep_notes ON deployment_owned.notes USING (true);
CREATE TABLE deployment_owned."quoted""name"("key""name" text PRIMARY KEY, money numeric(30,8), touched_at timestamptz);
